import { useState, useEffect } from "react";
import "./App.css";

export default function History({ userEmail, onBack }) {
  const [analyses, setAnalyses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedAnalysis, setSelectedAnalysis] = useState(null);

  useEffect(() => {
    fetchHistory();
  }, []);

  const fetchHistory = async () => {
    try {
      const res = await fetch(`http://localhost:8001/analysis_history/${userEmail}`);
      const data = await res.json();
      if (data.status === "success") {
        setAnalyses(data.analyses);
      } else {
        setError("Nu am putut încărca istoricul");
      }
    } catch (err) {
      setError("Eroare la încărcarea istoricului");
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (isoString) => {
    const date = new Date(isoString);
    return date.toLocaleDateString("ro-RO", {
      day: "2-digit",
      month: "long",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit"
    });
  };

  const renderNutritionBars = (nutrition) => {
    const maxCalories = 800;
    const maxProtein = 50;
    const maxCarbs = 100;
    const maxFat = 50;

    const totalNutrition = nutrition.total_nutrition || nutrition;

    return (
      <div style={{ marginTop: "1rem" }}>
        <div style={{ marginBottom: "0.8rem" }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.3rem" }}>
            <span style={{ fontSize: "0.9rem", color: "#666" }}>🔥 Calorii</span>
            <span style={{ fontSize: "0.9rem", fontWeight: "600", color: "#ff6b35" }}>
              {totalNutrition.calories} kcal
            </span>
          </div>
          <div style={{ 
            width: "100%", 
            height: "8px", 
            background: "#f0f0f0", 
            borderRadius: "10px",
            overflow: "hidden"
          }}>
            <div style={{ 
              width: `${Math.min((totalNutrition.calories / maxCalories) * 100, 100)}%`, 
              height: "100%", 
              background: "linear-gradient(90deg, #ff6b35, #ff8c42)",
              transition: "width 0.5s ease"
            }}></div>
          </div>
        </div>

        <div style={{ marginBottom: "0.8rem" }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.3rem" }}>
            <span style={{ fontSize: "0.9rem", color: "#666" }}>💪 Proteine</span>
            <span style={{ fontSize: "0.9rem", fontWeight: "600", color: "#4CAF50" }}>
              {totalNutrition.protein}g
            </span>
          </div>
          <div style={{ 
            width: "100%", 
            height: "8px", 
            background: "#f0f0f0", 
            borderRadius: "10px",
            overflow: "hidden"
          }}>
            <div style={{ 
              width: `${Math.min((totalNutrition.protein / maxProtein) * 100, 100)}%`, 
              height: "100%", 
              background: "linear-gradient(90deg, #4CAF50, #66BB6A)",
              transition: "width 0.5s ease"
            }}></div>
          </div>
        </div>

        <div style={{ marginBottom: "0.8rem" }}>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.3rem" }}>
            <span style={{ fontSize: "0.9rem", color: "#666" }}>🍞 Carbohidrați</span>
            <span style={{ fontSize: "0.9rem", fontWeight: "600", color: "#2196F3" }}>
              {totalNutrition.carbs}g
            </span>
          </div>
          <div style={{ 
            width: "100%", 
            height: "8px", 
            background: "#f0f0f0", 
            borderRadius: "10px",
            overflow: "hidden"
          }}>
            <div style={{ 
              width: `${Math.min((totalNutrition.carbs / maxCarbs) * 100, 100)}%`, 
              height: "100%", 
              background: "linear-gradient(90deg, #2196F3, #42A5F5)",
              transition: "width 0.5s ease"
            }}></div>
          </div>
        </div>

        <div>
          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.3rem" }}>
            <span style={{ fontSize: "0.9rem", color: "#666" }}>🥑 Grăsimi</span>
            <span style={{ fontSize: "0.9rem", fontWeight: "600", color: "#FFC107" }}>
              {totalNutrition.fat}g
            </span>
          </div>
          <div style={{ 
            width: "100%", 
            height: "8px", 
            background: "#f0f0f0", 
            borderRadius: "10px",
            overflow: "hidden"
          }}>
            <div style={{ 
              width: `${Math.min((totalNutrition.fat / maxFat) * 100, 100)}%`, 
              height: "100%", 
              background: "linear-gradient(90deg, #FFC107, #FFD54F)",
              transition: "width 0.5s ease"
            }}></div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="animated-bg" style={{ minHeight: "100vh", paddingBottom: "2rem" }}>
      <header className="header">
        <div className="header-content">
          <div className="logo" onClick={onBack} style={{ cursor: "pointer" }}>
            🍳 SmartChef
          </div>
        </div>
      </header>

      <div style={{ maxWidth: "1000px", margin: "0 auto", padding: "2rem" }}>
        <div style={{ textAlign: "center", marginBottom: "2rem" }}>
          <h2 style={{ fontSize: "2.5rem", fontWeight: "700", color: "#ff6b35", marginBottom: "0.5rem" }}>
            📊 Istoricul Analizelor
          </h2>
          <p style={{ color: "#666", fontSize: "1rem" }}>
            Toate analizele tale de mâncare
          </p>
        </div>

        <button
          className="btn btn-secondary"
          onClick={onBack}
          style={{ marginBottom: "2rem" }}
        >
          ← Înapoi
        </button>

        {loading && (
          <div style={{ textAlign: "center", padding: "3rem" }}>
            <div className="spinner"></div>
            <p style={{ marginTop: "1rem", color: "#666" }}>Se încarcă istoricul...</p>
          </div>
        )}

        {error && (
          <div style={{
            background: "#fee",
            border: "2px solid #fcc",
            borderRadius: "12px",
            padding: "1rem",
            textAlign: "center",
            color: "#c33"
          }}>
            ⚠️ {error}
          </div>
        )}

        {!loading && !error && analyses.length === 0 && (
          <div style={{
            textAlign: "center",
            padding: "3rem",
            background: "white",
            borderRadius: "20px",
            boxShadow: "0 10px 30px rgba(0,0,0,0.1)"
          }}>
            <p style={{ fontSize: "3rem", marginBottom: "1rem" }}>🍽️</p>
            <p style={{ fontSize: "1.2rem", color: "#666" }}>
              Nu ai încă nicio analiză.<br/>
              Uploadează prima ta imagine!
            </p>
          </div>
        )}

        {!loading && !error && analyses.length > 0 && (
          <div style={{ position: "relative" }}>
            {/* Timeline line */}
            <div style={{
              position: "absolute",
              left: "20px",
              top: "0",
              bottom: "0",
              width: "3px",
              background: "linear-gradient(180deg, #ff6b35, #ff8c42)",
              borderRadius: "10px"
            }}></div>

            {analyses.map((analysis, index) => (
              <div
                key={analysis._id}
                style={{
                  marginLeft: "50px",
                  marginBottom: "2rem",
                  position: "relative",
                  animation: `slideIn 0.5s ease ${index * 0.1}s backwards`
                }}
              >
                {/* Timeline dot */}
                <div style={{
                  position: "absolute",
                  left: "-38px",
                  top: "20px",
                  width: "16px",
                  height: "16px",
                  background: "#ff6b35",
                  borderRadius: "50%",
                  border: "3px solid white",
                  boxShadow: "0 0 0 3px #ff6b35"
                }}></div>

                <div
                  className="feature-card"
                  style={{
                    padding: "1.5rem",
                    cursor: selectedAnalysis?._id === analysis._id ? "default" : "pointer",
                    transform: selectedAnalysis?._id === analysis._id ? "scale(1.02)" : "scale(1)",
                    transition: "all 0.3s ease"
                  }}
                  onClick={() => setSelectedAnalysis(
                    selectedAnalysis?._id === analysis._id ? null : analysis
                  )}
                >
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "start", marginBottom: "1rem" }}>
                    <div>
                      <p style={{ fontSize: "0.85rem", color: "#999", marginBottom: "0.3rem" }}>
                        📅 {formatDate(analysis.timestamp)}
                      </p>
                      <p style={{ fontSize: "0.9rem", color: "#666" }}>
                        📁 {analysis.image_name}
                      </p>
                    </div>
                    <span style={{
                      background: "linear-gradient(135deg, #ff6b35, #ff8c42)",
                      color: "white",
                      padding: "0.3rem 0.8rem",
                      borderRadius: "20px",
                      fontSize: "0.85rem",
                      fontWeight: "600"
                    }}>
                      {analysis.ingredients.length} ingrediente
                    </span>
                  </div>

                  <div style={{ marginBottom: "1rem" }}>
                    <p style={{ fontSize: "0.9rem", fontWeight: "600", color: "#333", marginBottom: "0.5rem" }}>
                      🥗 Ingrediente detectate:
                    </p>
                    <div style={{ display: "flex", flexWrap: "wrap", gap: "0.5rem" }}>
                      {analysis.ingredients.map((ing, i) => (
                        <span
                          key={i}
                          style={{
                            background: "#f5f5f5",
                            padding: "0.4rem 0.8rem",
                            borderRadius: "15px",
                            fontSize: "0.85rem",
                            color: "#555"
                          }}
                        >
                          {ing}
                        </span>
                      ))}
                    </div>
                  </div>

                  {selectedAnalysis?._id === analysis._id && (
                    <div style={{
                      marginTop: "1.5rem",
                      paddingTop: "1.5rem",
                      borderTop: "2px solid #f0f0f0"
                    }}>
                      <p style={{ fontSize: "1rem", fontWeight: "600", color: "#333", marginBottom: "1rem" }}>
                        📊 Valori Nutriționale:
                      </p>
                      {renderNutritionBars(analysis.nutrition)}
                    </div>
                  )}

                  <p style={{
                    textAlign: "center",
                    marginTop: "1rem",
                    fontSize: "0.85rem",
                    color: "#999",
                    fontStyle: "italic"
                  }}>
                    {selectedAnalysis?._id === analysis._id 
                      ? "Click pentru a ascunde detaliile" 
                      : "Click pentru a vedea detaliile nutriționale"}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
